<script setup lang="ts">import{reactive}from'vue';import{Head,Link,router}from'@inertiajs/vue3';import{FileText,Search}from'@lucide/vue';import AppLayout from '@/Layouts/AppLayout.vue';const p=defineProps<{jobs:any,staff:any[],filters:any}>();const f=reactive({from:p.filters.from||'',to:p.filters.to||'',staff:p.filters.staff||'',witness:p.filters.witness||''});const load=()=>router.get('/dashboard/akta',f,{preserveState:true,replace:true});const date=(x:any)=>new Date(x).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'});</script><template><Head title="Daftar Akta"/><AppLayout><main class="mx-auto max-w-7xl space-y-6 p-4"><div><h1 class="text-2xl font-black">Daftar Akta</h1><p class="text-sm text-slate-500">Daftar seluruh akta berdasarkan client, PIC, dan saksi.</p></div><form @submit.prevent="load" class="grid gap-3 rounded-3xl border bg-white p-5 md:grid-cols-5"><input v-model="f.from" type="date" class="rounded-xl border-slate-200"/><input v-model="f.to" type="date" class="rounded-xl border-slate-200"/><select v-model="f.staff" class="rounded-xl border-slate-200"><option value="">Semua Pegawai</option><option v-for="s in staff" :value="s.id">{{s.fullName}}</option></select><div class="relative"><Search class="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input v-model="f.witness" class="w-full rounded-xl border-slate-200 pl-9" placeholder="Nama saksi"/></div><button class="rounded-xl bg-pink-500 font-bold text-white">Terapkan</button></form><section class="overflow-hidden rounded-3xl border bg-white"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4 pl-6">No.</th><th>Tanggal Berkas</th><th>Nama Client</th><th>Jenis Pekerjaan</th><th>PIC Pegawai</th><th>Nama Saksi</th></tr></thead><tbody><tr v-if="!jobs.data.length"><td colspan="6" class="py-16 text-center text-slate-400"><FileText class="mx-auto mb-3 h-10 w-10 opacity-30"/>Data tidak ditemukan.</td></tr><tr v-for="(j,i) in jobs.data" class="border-t hover:bg-slate-50"><td class="p-4 pl-6">{{i+1}}</td><td>{{date(j.createdAt)}}</td><td class="font-bold">{{j.clientName||'-'}}</td><td><Link :href="`/dashboard/jobs/${j.jobType}/${j.id}`" class="font-bold hover:text-pink-500">{{j.title}}</Link><p class="text-xs text-slate-500">{{j.category}}</p></td><td>{{j.staffName||'-'}}</td><td>{{j.saksi||'-'}}</td></tr></tbody></table></div></section></main></AppLayout></template>
